window.QSTUDY=[[91,"Аш-Шамс",[[1,"Клянусь солнцем и его утренним сиянием!",[["وَالشَّمْسِ",[["وَ",0,"«клянусь» (вав клятвы)"],["ٱل",1],["شَّمْسِ",405]]],["وَضُحَاهَا",[["وَ",0],["ضُحَىٰ",406],["هَا","местоимение: она / её"]]]]],[2,"Клянусь луной, когда она следует за ним!",[["وَالْقَمَرِ",[["وَ",0],["ٱلْ",1],["قَمَرِ",407]]],["إِذَا",[["إِذَا",29]]],["تَلَاهَا",[["تَلَىٰ",193],["هَا","местоимение: она / её"]]]]],[3,"Клянусь днем, когда он делает его (солнце) ясным!",[["وَالنَّهَارِ",[["وَ",0],["ٱل",1],["نَّهَارِ",205]]],["إِذَا",[["إِذَا",29]]],["جَلَّاهَا",[["جَلَّىٰ",408],["هَا","местоимение: она / её"]]]]],[4,"Клянусь ночью, когда она скрывает его (солнце)!",[["وَاللَّيْلِ",[["وَ",0],["ٱلَّ",1],["يْلِ",131]]],["إِذَا",[["إِذَا",29]]],["يَغْشَاهَا",[["يَغْشَىٰ",409],["هَا","местоимение: она / её"]]]]],[5,"Клянусь небом и Тем, Кто его воздвиг (или тем, как Он воздвиг его)!",[["وَالسَّمَاءِ",[["وَ",0],["ٱل",1],["سَّمَآءِ",40]]],["وَمَا",[["وَ",0],["مَا",11]]],["بَنَاهَا",[["بَنَىٰ",410],["هَا","местоимение: она / её"]]]]],[6,"Клянусь землей и Тем, Кто ее распростер (или тем, как Он распростер ее)!",[["وَالْأَرْضِ",[["وَ",0],["ٱلْ",1],["أَرْضِ",27]]],["وَمَا",[["وَ",0],["مَا",11]]],["طَحَاهَا",[["طَحَىٰ",411],["هَا","местоимение: она / её"]]]]],[7,"Клянусь душой и Тем, Кто придал ей совершенный облик (или тем, как Он сделал ее облик совершенным)",[["وَنَفْسٍ",[["وَ",0],["نَفْسٍ",42]]],["وَمَا",[["وَ",0],["مَا",11]]],["سَوَّاهَا",[["سَوَّىٰ",412],["هَا","местоимение: она / её"]]]]],[8,"…и внушил ей порочность ее и богобоязненность!",[["فَأَلْهَمَهَا",[["فَ",4],["أَلْهَمَ",413],["هَا","местоимение: она / её"]]],["فُجُورَهَا",[["فُجُورَ",414],["هَا","местоимение: она / её"]]],["وَتَقْوَاهَا",[["وَ",0],["تَقْوَىٰ",415],["هَا","местоимение: она / её"]]]]],[9,"Преуспел тот, кто очистил ее…",[["قَدْ",[["قَدْ",28]]],["أَفْلَحَ",[["أَفْلَحَ",416]]],["مَنْ",[["مَن",18]]],["زَكَّاهَا",[["زَكَّىٰ",417],["هَا","местоимение: она / её"]]]]],[10,"…и понес урон тот, кто скрыл ее (опорочил, облек в несправедливость).",[["وَقَدْ",[["وَ",0],["قَدْ",28]]],["خَابَ",[["خَابَ",418]]],["مَنْ",[["مَن",18]]],["دَسَّاهَا",[["دَسَّىٰ",419],["هَا","местоимение: она / её"]]]]],[11,"Самудяне сочли лжецом пророка Салиха из-за своего беззакония…",[["كَذَّبَتْ",[["كَذَّبَتْ",66]]],["ثَمُودُ",[["ثَمُودُ",420]]],["بِطَغْوَاهَا",[["بِ",6],["طَغْوَىٰ",421],["هَآ","местоимение: она / её"]]]]],[12,"…и тогда самый несчастный из них вызвался убить верблюдицу.",[["إِذِ",[["إِذِ",41]]],["انْبَعَثَ",[["ٱنۢبَعَثَ",422]]],["أَشْقَاهَا",[["أَشْقَىٰ",423],["هَا","местоимение: она / её"]]]]],[13,"Посланник Аллаха (Салих) сказал им: «Берегите верблюдицу и питье ее!».",[["فَقَالَ",[["فَ",4],["قَالَ",10]]],["لَهُمْ",[["لَ",2],["هُمْ","местоимение: они / их / им"]]],["رَسُولُ",[["رَسُولُ",38]]],["اللَّهِ",[["ٱللَّهِ",5]]],["نَاقَةَ",[["نَاقَةَ",424]]],["اللَّهِ",[["ٱللَّهِ",5]]],["وَسُقْيَاهَا",[["وَ",0],["سُقْيَٰ",425],["هَا","местоимение: она / её"]]]]],[14,"Они сочли его лжецом и подрезали ей поджилки, и за этот грех Господь их подверг их наказанию, которое было одинаковым для всех (или сровнял над ними землю).",[["فَكَذَّبُوهُ",[["فَ",4],["كَذَّبُ",66],["و","местоимение: они / их / им"],["هُ","местоимение: он / его / ему"]]],["فَعَقَرُوهَا",[["فَ",4],["عَقَرُ",426],["و","местоимение: они / их / им"],["هَا","местоимение: она / её"]]],["فَدَمْدَمَ",[["فَ",4],["دَمْدَمَ",427]]],["عَلَيْهِمْ",[["عَلَيْ",13],["هِمْ","местоимение: они / их / им"]]],["رَبُّهُمْ",[["رَبُّ",16],["هُم","местоимение: они / их / им"]]],["بِذَنْبِهِمْ",[["بِ",6],["ذَنۢبِ",428],["هِمْ","местоимение: они / их / им"]]],["فَسَوَّاهَا",[["فَ",4],["سَوَّىٰ",412],["هَا","местоимение: она / её"]]]]],[15,"И не опасался Он последствий этого.",[["وَلَا",[["وَ",0],["لَا",7]]],["يَخَافُ",[["يَخَافُ",135]]],["عُقْبَاهَا",[["عُقْبَٰ",429],["هَا","местоимение: она / её"]]]]]]]];
window.QSURA={"91":{"s":91,"name":"Аш-Шамс","ar":"الشَّمْس","mean":"Солнце","facts":[["Где ниспослана","в Мекке"],["Аятов","15"],["Часть (джуз)","30-я"],["Название","по первому слову: وَالشَّمْسِ — «клянусь солнцем»"],["Главная тема","очищение души: кто очистил её — преуспел, кто запустил — проиграл"]],"about":["Сура начинается с одиннадцати клятв подряд — солнцем, его сиянием, луной, днём, ночью, небом и Тем, Кто его воздвиг, землёй и Тем, Кто её распростёр, душой и Тем, Кто её соразмерил. По подсчёту толкователей, это самый длинный ряд клятв в одном месте Корана.","Все клятвы ведут к одному ответу (аяты 9–10): قَدْ أَفْلَحَ مَنْ زَكَّاهَا — «преуспел тот, кто очистил её», и потерпел неудачу тот, кто её запустил. Чем весомее клятва, тем важнее то, ради чего клянутся.","Вторая часть (аяты 11–15) — пример из истории: народ Самуд не очистил душу, отверг пророка Салиха и убил верблюдицу — знамение Аллаха — и погиб."],"tafsir":{"1":"Аллах клянётся солнцем и его утренним сиянием — светом и теплом, когда солнце уже поднялось. Аллах клянётся Своими творениями, чтобы обратить на них внимание: в них знамения Его могущества.","2":"Клятва луной, когда она следует за солнцем: восходит после его заката и светит отражённым светом.","3":"Клятва днём, когда он делает солнце ясным и видимым. По другому толкованию, местоимение относится к земле: день освещает её и открывает всё, что на ней.","4":"Клятва ночью, когда она покрывает солнце и мир мраком. Сменяющие друг друга день и ночь — знак порядка, установленного Творцом.","5":"Клятва небом и Тем, Кто его воздвиг, — Аллахом. Частицу وَمَا толкователи понимают двояко: «и Тем, Кто воздвиг» или «и тем, как оно воздвигнуто»; перевод Кулиева приводит оба.","6":"Клятва землёй и Тем, Кто её распростёр и сделал пригодной для жизни.","7":"Клятва душой и Тем, Кто её соразмерил: создал человека в совершенном облике и с врождённой природой (фитрой), готовой принять истину.","8":"Аллах внушил душе, что есть нечестие и что — богобоязненность: дал ей различать добро и зло. Выбор пути оставлен человеку, и за него он ответит.","9":"Это ответ на все клятвы: преуспел тот, кто очистил душу — повиновением Аллаху, благими делами, отказом от грехов.","10":"И потерпел неудачу тот, кто «погрёб» свою душу: запустил её, скрыл в грехах и лишил блага.","11":"Пример из истории: народ Самуд из-за своего беззакония счёл ложью своего пророка Салиха.","12":"Когда поднялся самый несчастный из них, чтобы убить верблюдицу. По словам толкователей, его звали Кудар ибн Салиф; он был знатным и сильным в своём роду.","13":"Посланник Аллаха — пророк Салих — предостерёг их: не трогайте верблюдицу Аллаха и не мешайте её дню у водопоя. Вода делилась по очереди: день пила верблюдица, день — люди.","14":"Они сочли его лжецом и убили верблюдицу. Убил один, но остальные были согласны с ним, поэтому грех лёг на всех. Аллах обрушил на них гибель за их грех и «сравнял» их — наказание постигло всех одинаково, никто не спасся.","15":"И Аллах не опасается последствий Своего наказания: никто не может потребовать с Него ответа. Есть и другое толкование — «и не боялся он (убийца) последствий своего дела»; первое — мнение большинства толкователей."},"story":{"title":"История народа Самуд","text":["Самуд — древний арабский народ. Они жили в аль-Хиджре, на севере Аравии, и высекали себе дома в скалах. Аллах послал к ним пророка Салиха.","Народ потребовал знамения, и Аллах дал им верблюдицу — «верблюдицу Аллаха». Салих запретил причинять ей зло и установил очередь у воды: «У неё — доля питья, и у вас — доля питья в известный день» (26:155).","Самые нечестивые из них сговорились и убили верблюдицу. Салих сказал: «Наслаждайтесь в своих жилищах три дня» (11:65). После этого их поразил вопль (11:67) и сотрясение (7:78), и наутро они лежали бездыханными в своих домах.","Об этой истории подробнее — в сурах аль-Араф (7:73–79), Худ (11:61–68), аш-Шуара (26:141–159), ан-Намль (27:45–53)."]},"hadith":[{"ctx":"Сподвижник Муаз ибн Джабаль молился ночной намаз (иша) за Пророком ﷺ, а потом шёл к своему племени и вёл их в том же намазе как имам. Однажды вечером он начал читать длинную суру аль-Бакара. Один из молящихся весь день работал — поливал поля с помощью верблюдов. Он не выдержал долгого стояния, вышел из общего намаза и помолился отдельно. Муаз осудил его, и тот пожаловался Пророку ﷺ.","ar":"يَا مُعَاذُ أَفَتَّانٌ أَنْتَ فَلَوْلَا صَلَّيْتَ بِسَبِّحِ اسْمَ رَبِّكَ وَالشَّمْسِ وَضُحَاهَا وَاللَّيْلِ إِذَا يَغْشَى فَإِنَّهُ يُصَلِّي وَرَاءَكَ الْكَبِيرُ وَالضَّعِيفُ وَذُو الْحَاجَةِ","ru":"Пророк ﷺ трижды сказал: «О Муаз, неужели ты вводишь людей в смуту (отталкиваешь их от намаза)? Почему бы тебе не читать „Прославь имя Господа твоего Всевышнего“ (сура 87), „Клянусь солнцем и его сиянием“ (сура 91) и „Клянусь ночью, когда она покрывает“ (сура 92)? Ведь за тобой молятся старый, слабый и тот, у кого есть дела».","grade":"сахих","why":"Пророк ﷺ назвал эти суры не как особую награду за их чтение, а как меру длины для общего намаза. Имам отвечает за всех, кто стоит за ним: среди них старики, больные и люди, которые спешат по делам. Если он затягивает намаз, он утомляет их и может оттолкнуть от общего намаза — это Пророк ﷺ и назвал «смутой». Та же мысль в другом достоверном хадисе: «Когда кто-то из вас ведёт людей в намазе, пусть облегчает — ведь среди них есть слабый, больной и старый. А когда молится один, пусть удлиняет сколько пожелает» (сахих). Отсюда правило: ведёшь намаз — читай умеренно, суры вроде аш-Шамс как раз подходят; молишься один — можно читать сколько хочешь."},{"ctx":"Это часть мольбы, которую Пророк ﷺ говорил сам и которой учил сподвижников. Слова в ней взяты прямо из этой суры: تَقْوَاهَا «её богобоязненность» — из аята 8 (Аллах внушил душе её нечестие и её богобоязненность), زَكِّهَا «очисти её» и مَنْ زَكَّاهَا «тот, кто её очистил» — из аята 9.","ar":"اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّهَا وَمَوْلَاهَا","ru":"«О Аллах, даруй моей душе её богобоязненность и очисти её — Ты лучший из тех, кто может её очистить, Ты её Покровитель и Господин».","grade":"сахих","why":"Сура говорит: «преуспел тот, кто очистил душу». Мольба показывает, как к этому идти: очищение — это и собственный труд (повиновение, отказ от грехов), и просьба к Аллаху, потому что без Его помощи человек не очистит себя сам. Эту мольбу полезно выучить наизусть и повторять."},{"ctx":"Пророк ﷺ говорил проповедь и упомянул верблюдицу пророка Салиха и того, кто её убил. Он прочитал аят «когда поднялся самый несчастный из них» (91:12) и объяснил, кем был этот человек.","ar":"انْبَعَثَ لَهَا رَجُلٌ عَزِيزٌ عَارِمٌ مَنِيعٌ فِي رَهْطِهِ مِثْلُ أَبِي زَمْعَةَ","ru":"«Поднялся на это человек могущественный, злой и неприступный в своём роду — подобный Абу Зам‘е».","grade":"сахих","why":"Абу Зам‘а — знатный и сильный курайшит того времени, которого слушатели хорошо знали. Пророк ﷺ сравнил убийцу с ним, чтобы было понятно: это был не одиночка-безумец, а влиятельный человек, за которым стоял его род, и никто его не остановил. Поэтому толкователи объясняют аят 14 так: убил один, но остальные поддержали его и были довольны — и наказание постигло всех."}],"lessons":["Успех — не богатство и не положение, а чистота души (аят 9).","Душа знает добро и зло (аят 8); выбор и ответ — за человеком.","Очищение — это постоянный труд: повиновение, покаяние, отказ от грехов. Мольба из хадиса выше — готовые слова для этого.","Молчаливое согласие со злом делает соучастником: верблюдицу убил один, а наказаны все, кто был доволен (аят 14).","Ведёшь намаз — не утомляй людей: Пророк ﷺ указал на эту суру как на меру длины для общего намаза, потому что за имамом стоят старые, слабые и занятые люди. Молишься один — можно удлинять."],"lessons_title":"Выводы из суры","lessons_note":"Сформулированы по толкованию аятов (Ибн Касир, ас-Саади, аль-Куртуби) и хадисам выше — это пересказ смысла, не цитаты."}};
